// The torture suite: shapes deliberately pushed past what the rest of
// `src/wire/tests/` exercises — nesting deeper than `primitive_nesting.rs`'s
// cap of 3, list/group cardinalities in the hundreds/thousands instead of
// single digits, and multi-byte validity bitmasks instead of the
// single-byte masks every other file's 3-element examples produce.
//
// `expected_buf`/`expected_inodes` for the large-cardinality cases below
// (the 1000-element list, the 100-field group) are generated by a `const
// fn` applying the same little-endian/sequential-offset formula the
// smaller hand-written tests elsewhere in this suite already established
// and pinned byte-for-byte (`primitive_slice.rs`'s `BASIC_U32_LIST`,
// `primitive_group.rs`'s same-alignment field ordering) — not by copying
// the writer's own output. Writing 4000+ literal bytes by hand would be
// both impractical and no more trustworthy than a formula anyone can
// re-derive by inspection.
//
// The deep-nesting cases' pointer-chain bytes are the one exception:
// `src/wire/writers/nested_list.rs`'s multi-level topology format has
// enough internal bookkeeping (per-level indirection words, a trailing
// cumulative-boundary pair) that re-deriving it from scratch for 3 extra
// levels would just be transcribing the same algorithm a second time.
// Same position `primitive_nesting.rs`'s own `triple_nested_list_bytes`
// comment already stakes out: the invariants that matter (total length,
// payload pointer landing exactly where the payload starts, leaf count)
// are checked by hand below; the exact intermediate pointer values were
// confirmed against the real writer once and pinned, the same way that
// file's depth-3 case was.

#[cfg(test)]
use pyro_schema::PrimitiveDataType;
#[cfg(test)]
use pyro_schema::human::{PyroField, PyroSchema, PyroType};

#[cfg(test)]
use crate::{
    PyroValue, value::PrimitiveValueList, wire::tests::support::run_list_wrapped_roundtrip_u32,
};

use pyro_schema::{Inode, KindMeta, WireKind};

// ---------------------------------------------------------------------------
// Deep nesting: depth 4, 5 (primitive_nesting.rs caps out at 3)
// ---------------------------------------------------------------------------
//
// Each case is `List<List<...<List<u32>>...>>` (N `List` layers) holding a
// single chain of singleton lists down to one two-element leaf `[11, 22]`
// — minimal branching so the pointer-chain shape stays legible: every level
// above the leaf has exactly one child, so its own bookkeeping is a single
// 4-byte pointer to the next level, rather than a whole lengths array.
// Layout observed at each depth (data_offset 8 because a multi-level nested
// list always reserves a `(payload_start, leaf_count)` pair distinct from
// the shared `(topology_start, topology_end)` pair at offset 0 — see
// `primitive_nesting.rs`'s `list_of_list_u64`, also `data_offset: 8`):
//   [0..8)   topology_start=16, topology_end=20
//   [8..16)  payload_start, leaf_count=2
//   [16..N)  one 4-byte pointer per intermediate level, each pointing at
//            the next 4 bytes, until the final cumulative-boundary pair
//            [0, 2] (the leaf list's own start/end)
//   [N..)    payload: 11, 22 (both u32, little-endian)
// Depth 4 has 4 intermediate-pointer words, depth 5 has 6 —
// each extra `List` layer adds exactly one more 4-byte pointer.

pub const DEPTH_4_NESTED_U32: [u8; 48] = [
    16, 0, 0, 0, // 0 topology start pointer
    6, 0, 0, 0, // 4 topology end pointer
    40, 0, 0, 0, // 8 payload start pointer
    2, 0, 0, 0, // 12 leaf count
    255, 255, 255, 255, // 16 level pointer
    1, 0, 0, 0, // 20 level pointer
    255, 255, 255, 255, // 24 level pointer
    1, 0, 0, 0, // 28 level pointer
    255, 255, 255, 255, // 32 leaf list cumulative boundary: starts at 0
    2, 0, 0, 0, // 36 leaf list cumulative boundary: ends at 2
    11, 0, 0, 0, // 40 payload[0] = 11
    22, 0, 0, 0, // 44 payload[1] = 22
];
pub const DEPTH_4_NESTED_U32_INODES: [Inode; 1] = [Inode {
    kind: WireKind::U32,
    kind_meta: KindMeta::Primitive {
        nesting: 4,
        data_offset: 8,
        topology_offset: 0,
        fixed_size: 0,
        nullable_bit_index: 0,
        group: false,
        group_nest: false,
    },
}];

#[cfg_attr(test, tracing_test::traced_test)]
#[test]
fn test_nesting_depth_4() {
    let schema = nested_list_schema(4);
    let data = nested_list_value(4);

    run_list_wrapped_roundtrip_u32(
        schema,
        data,
        &DEPTH_4_NESTED_U32,
        &DEPTH_4_NESTED_U32_INODES,
    );
}

pub const DEPTH_5_NESTED_U32: [u8; 56] = [
    16, 0, 0, 0, // topology start pointer
    8, 0, 0, 0, // topology count
    48, 0, 0, 0, // payload start pointer
    2, 0, 0, 0, // leaf count
    255, 255, 255, 255, // level pointer
    1, 0, 0, 0, // level pointer
    255, 255, 255, 255, // level pointer
    1, 0, 0, 0, // level pointer
    255, 255, 255, 255, // level pointer
    1, 0, 0, 0, // level pointer
    255, 255, 255, 255, // leaf list cumulative boundary: starts at 0
    2, 0, 0, 0, // leaf list cumulative boundary: ends at 2
    11, 0, 0, 0, // payload[0] = 11
    22, 0, 0, 0, // payload[1] = 22
];
pub const DEPTH_5_NESTED_U32_INODES: [Inode; 1] = [Inode {
    kind: WireKind::U32,
    kind_meta: KindMeta::Primitive {
        nesting: 5,
        data_offset: 8,
        topology_offset: 0,
        fixed_size: 0,
        nullable_bit_index: 0,
        group: false,
        group_nest: false,
    },
}];

#[cfg_attr(test, tracing_test::traced_test)]
#[test]
fn test_nesting_depth_5() {
    let schema = nested_list_schema(5);
    let data = nested_list_value(5);

    run_list_wrapped_roundtrip_u32(
        schema,
        data,
        &DEPTH_5_NESTED_U32,
        &DEPTH_5_NESTED_U32_INODES,
    );
}

/// `List<List<...<List<u32>>...>>` with `n` `List` layers total.
#[cfg(test)]
fn nested_list_schema(n: usize) -> PyroSchema {
    let mut ty = PyroType::PrimitiveScalar {
        primitive: PrimitiveDataType::U32,
    };
    for _ in 0..n {
        ty = PyroType::List {
            element: Box::new(ty),
        };
    }
    PyroSchema {
        doc: String::new(),
        fields: vec![PyroField {
            name: "a".to_string(),
            doc: String::new(),
            data_type: ty,
        }],
    }
}

/// A chain of `n - 1` singleton `List`s wrapping one two-element leaf
/// `PrimitiveList`, matching `nested_list_schema(n)`.
#[cfg(test)]
fn nested_list_value(n: usize) -> PyroValue<'static> {
    let mut v = PyroValue::PrimitiveList(PrimitiveValueList::U32(vec![11, 22].into()));
    for _ in 0..(n - 1) {
        v = PyroValue::List(vec![v]);
    }
    v
}

// ---------------------------------------------------------------------------
// 1000-element list
// ---------------------------------------------------------------------------
//
// Same wire shape as `primitive_slice.rs`'s `BASIC_U32_LIST` (`[topology
// size (always 8), element count, ...little-endian u32 payload]`) at a
// cardinality none of those hand-written cases reach — large enough to
// catch an off-by-one that only shows up once the payload crosses a page
// or spills past whatever a smaller test's buffer would fit in.

const fn build_large_u32_list_buf() -> [u8; 4008] {
    let mut buf = [0u8; 4008];
    let topology_size = 8u32.to_le_bytes();
    let mut i = 0;
    while i < 4 {
        buf[i] = topology_size[i];
        i += 1;
    }
    let count = 1000u32.to_le_bytes();
    i = 0;
    while i < 4 {
        buf[4 + i] = count[i];
        i += 1;
    }
    let mut elem = 0usize;
    while elem < 1000 {
        let bytes = (elem as u32).to_le_bytes();
        let base = 8 + elem * 4;
        buf[base] = bytes[0];
        buf[base + 1] = bytes[1];
        buf[base + 2] = bytes[2];
        buf[base + 3] = bytes[3];
        elem += 1;
    }
    buf
}
pub const LARGE_U32_LIST: [u8; 4008] = build_large_u32_list_buf();
pub const LARGE_U32_LIST_INODES: [Inode; 1] = [Inode {
    kind: WireKind::U32,
    kind_meta: KindMeta::Primitive {
        nesting: 1,
        data_offset: 0,
        topology_offset: 0,
        fixed_size: 0,
        nullable_bit_index: 0,
        group: false,
        group_nest: false,
    },
}];

#[cfg_attr(test, tracing_test::traced_test)]
#[test]
fn test_large_list_1000_elements() {
    let schema = PyroSchema {
        doc: String::new(),
        fields: vec![PyroField {
            name: "a".to_string(),
            doc: String::new(),
            data_type: PyroType::List {
                element: Box::new(PyroType::PrimitiveScalar {
                    primitive: PrimitiveDataType::U32,
                }),
            },
        }],
    };

    let data = PyroValue::from((0..1000u32).collect::<Vec<u32>>());

    run_list_wrapped_roundtrip_u32(schema, data, &LARGE_U32_LIST, &LARGE_U32_LIST_INODES);
}

// ---------------------------------------------------------------------------
// 100-field group
// ---------------------------------------------------------------------------
//
// All 100 fields share one `U8` primitive type (alignment 1), so
// `primitive_group.rs`'s bucket-sort-by-descending-alignment rule ties
// every field in the same bucket and falls back to ascending declaration
// order — offsets land at exactly `0..100` in field order, same rule that
// small same-alignment group cases (`GROUP_PAIR_U16_U16` etc.) already pin.

const fn u8_field_inode(offset: u16) -> Inode {
    Inode {
        kind: WireKind::U8,
        kind_meta: KindMeta::Primitive {
            nesting: 0,
            data_offset: offset,
            topology_offset: 0,
            fixed_size: 0,
            nullable_bit_index: 0,
            group: false,
            group_nest: false,
        },
    }
}

const fn build_group_100_inodes() -> [Inode; 100] {
    let mut arr = [u8_field_inode(0); 100];
    let mut i = 0usize;
    while i < 100 {
        arr[i] = u8_field_inode(i as u16);
        i += 1;
    }
    arr
}
pub const GROUP_100_U8_FIELDS_INODES: [Inode; 100] = build_group_100_inodes();

const fn build_group_100_buf() -> [u8; 100] {
    let mut buf = [0u8; 100];
    let mut i = 0usize;
    while i < 100 {
        buf[i] = i as u8;
        i += 1;
    }
    buf
}
pub const GROUP_100_U8_FIELDS: [u8; 100] = build_group_100_buf();

#[cfg(test)]
fn leaked(s: String) -> &'static str {
    Box::leak(s.into_boxed_str())
}

#[cfg_attr(test, tracing_test::traced_test)]
#[test]
fn test_group_100_fields() {
    let fields: Vec<PyroField> = (0..100)
        .map(|i| PyroField {
            name: format!("f{i}"),
            doc: String::new(),
            data_type: PyroType::PrimitiveScalar {
                primitive: PrimitiveDataType::U8,
            },
        })
        .collect();
    let schema = PyroSchema {
        doc: String::new(),
        fields,
    };

    let data = PyroValue::Group(
        (0..100u8)
            .map(|i| (leaked(format!("f{i}")), PyroValue::from(i)))
            .collect(),
    );

    run_list_wrapped_roundtrip_u32(
        schema,
        data,
        &GROUP_100_U8_FIELDS,
        &GROUP_100_U8_FIELDS_INODES,
    );
}

// ---------------------------------------------------------------------------
// Extreme string / bytes lengths
// ---------------------------------------------------------------------------
//
// Same shape `basic.rs` pins for a bare `Str`/`Bytes` field (`[data_ptr=8,
// data_len, ...payload]`, see `STR_BASIC`/`BYTES_BASIC`) at a length no
// other test in this suite approaches — large enough to exercise a
// multi-page dynamic-region allocation instead of a handful of bytes.

const STR_EXTREME_LEN: usize = 50_000;

const fn build_str_extreme_buf() -> [u8; 8 + STR_EXTREME_LEN] {
    let mut buf = [b'q'; 8 + STR_EXTREME_LEN];
    let ptr = 8u32.to_le_bytes();
    let len = (STR_EXTREME_LEN as u32).to_le_bytes();
    let mut i = 0;
    while i < 4 {
        buf[i] = ptr[i];
        buf[4 + i] = len[i];
        i += 1;
    }
    buf
}
pub const STR_EXTREME: [u8; 8 + STR_EXTREME_LEN] = build_str_extreme_buf();
pub const STR_EXTREME_INODES: [Inode; 1] = [Inode {
    kind: WireKind::Str,
    kind_meta: KindMeta::Primitive {
        nesting: 0,
        data_offset: 0,
        topology_offset: 0,
        fixed_size: 0,
        nullable_bit_index: 0,
        group: false,
        group_nest: false,
    },
}];

#[cfg_attr(test, tracing_test::traced_test)]
#[test]
fn test_str_extreme_length() {
    let schema = PyroSchema {
        doc: String::new(),
        fields: vec![PyroField {
            name: "a".to_string(),
            doc: String::new(),
            data_type: PyroType::Str,
        }],
    };

    let data = PyroValue::Str("q".repeat(STR_EXTREME_LEN).into());

    run_list_wrapped_roundtrip_u32(schema, data, &STR_EXTREME, &STR_EXTREME_INODES);
}

const BYTES_EXTREME_LEN: usize = 50_000;

const fn build_bytes_extreme_buf() -> [u8; 8 + BYTES_EXTREME_LEN] {
    let mut buf = [0u8; 8 + BYTES_EXTREME_LEN];
    let ptr = 8u32.to_le_bytes();
    let len = (BYTES_EXTREME_LEN as u32).to_le_bytes();
    let mut i = 0;
    while i < 4 {
        buf[i] = ptr[i];
        buf[4 + i] = len[i];
        i += 1;
    }
    let mut j = 0usize;
    while j < BYTES_EXTREME_LEN {
        buf[8 + j] = (j % 256) as u8;
        j += 1;
    }
    buf
}
pub const BYTES_EXTREME: [u8; 8 + BYTES_EXTREME_LEN] = build_bytes_extreme_buf();
pub const BYTES_EXTREME_INODES: [Inode; 1] = [Inode {
    kind: WireKind::Bytes,
    kind_meta: KindMeta::Primitive {
        nesting: 0,
        data_offset: 0,
        topology_offset: 0,
        fixed_size: 0,
        nullable_bit_index: 0,
        group: false,
        group_nest: false,
    },
}];

#[cfg_attr(test, tracing_test::traced_test)]
#[test]
fn test_bytes_extreme_length() {
    let schema = PyroSchema {
        doc: String::new(),
        fields: vec![PyroField {
            name: "a".to_string(),
            doc: String::new(),
            data_type: PyroType::Bytes,
        }],
    };

    let data = PyroValue::Bytes((0..BYTES_EXTREME_LEN).map(|j| (j % 256) as u8).collect());

    run_list_wrapped_roundtrip_u32(schema, data, &BYTES_EXTREME, &BYTES_EXTREME_INODES);
}

// ---------------------------------------------------------------------------
// Multi-row nullability matrices
// ---------------------------------------------------------------------------
//
// Every `Option`-list case elsewhere in this suite (`primitive_slice_
// option.rs`) uses exactly 3 elements — one validity byte, no bit ever
// crosses a byte boundary. Both cases below use a null-every-third-row
// pattern long enough (20 rows) to force the validity bitmap across
// multiple bytes, which is the part a single-byte case can never catch:
// a boundary bug (e.g. treating the mask as 8 independent single-byte
// masks instead of one continuous bitstream) would only show up here.
//
// Null pattern (row index -> present?): present iff `index % 3 != 0`, so
// rows 0, 3, 6, 9, 12, 15, 18 are null (7 of 20) and the rest hold their
// own index as the value. Per-bit validity (`Lsb0`, bit N set iff row N is
// present), grouped into bytes:
//   byte0 (rows 0-7):   0,1,1,0,1,1,0,1 -> 0b1011_0110 = 182
//   byte1 (rows 8-15):  1,0,1,1,0,1,1,0 -> 0b0110_1101 = 109
//   byte2 (rows 16-19): 1,1,0,1 (bits 4-7 unused, zero) -> 0b0000_1011 = 11

/// `List<Option<u32>>`, 20 elements — one validity byte per case in
/// `primitive_slice_option.rs`'s 3-element examples is never enough to
/// prove the bit-packing survives a byte boundary; this crosses two.
pub const NULLABILITY_LIST_OPTION_U32_20: [u8; 67] = [
    12, 0, 0, 0, // fixed: offset to payload (12-byte header, u32-aligned)
    13, 0, 0, 0, // fixed: present (non-null) count
    20, 0, 0, 0, // fixed: total element count (including nulls)
    1, 0, 0, 0, // payload[0] = row 1
    2, 0, 0, 0, // payload[1] = row 2
    4, 0, 0, 0, // payload[2] = row 4
    5, 0, 0, 0, // payload[3] = row 5
    7, 0, 0, 0, // payload[4] = row 7
    8, 0, 0, 0, // payload[5] = row 8
    10, 0, 0, 0, // payload[6] = row 10
    11, 0, 0, 0, // payload[7] = row 11
    13, 0, 0, 0, // payload[8] = row 13
    14, 0, 0, 0, // payload[9] = row 14
    16, 0, 0, 0, // payload[10] = row 16
    17, 0, 0, 0, // payload[11] = row 17
    19, 0, 0, 0, // payload[12] = row 19
    182, 109, 11, // validity bitmap,
];
pub const NULLABILITY_LIST_OPTION_U32_20_INODES: [Inode; 1] = [Inode {
    kind: WireKind::OptionU32,
    kind_meta: KindMeta::Primitive {
        nesting: 1,
        data_offset: 0,
        topology_offset: 0,
        fixed_size: 0,
        nullable_bit_index: 0,
        group: false,
        group_nest: false,
    },
}];

#[cfg_attr(test, tracing_test::traced_test)]
#[test]
fn test_nullability_list_option_u32_20() {
    let schema = PyroSchema {
        doc: String::new(),
        fields: vec![PyroField {
            name: "a".to_string(),
            doc: String::new(),
            data_type: PyroType::List {
                element: Box::new(PyroType::OptionPrimitiveScalar {
                    primitive: PrimitiveDataType::U32,
                }),
            },
        }],
    };

    let data: Vec<Option<u32>> = (0..20u32)
        .map(|i| if i % 3 == 0 { None } else { Some(i) })
        .collect();
    let data = PyroValue::from(data);

    run_list_wrapped_roundtrip_u32(
        schema,
        data,
        &NULLABILITY_LIST_OPTION_U32_20,
        &NULLABILITY_LIST_OPTION_U32_20_INODES,
    );
}

/// Same null-every-third-row pattern, but as 20 independent `Option<Bool>`
/// *fields* of one `Group` instead of one list's elements — a completely
/// separate validity-bitmap code path (`layout_nullable_section`'s shared,
/// declaration-order `nullable_bit_index` counter — see
/// `primitive_group_option.rs`'s doc comment) that deserves its own
/// byte-boundary-crossing case. All 20 fields share alignment 1
/// (`OptionBool`), so they bucket-sort into declaration order, same rule
/// `test_group_100_fields` above exercises for a non-nullable group.
const fn option_bool_field_inode(offset: u16, nullable_bit_index: u16) -> Inode {
    Inode {
        kind: WireKind::OptionBool,
        kind_meta: KindMeta::Primitive {
            nesting: 0,
            data_offset: offset,
            topology_offset: 0,
            fixed_size: 0,
            nullable_bit_index,
            group: false,
            group_nest: false,
        },
    }
}

const fn build_group_20_option_bool_inodes() -> [Inode; 20] {
    let mut arr = [option_bool_field_inode(0, 0); 20];
    let mut i = 0usize;
    while i < 20 {
        arr[i] = option_bool_field_inode(i as u16, i as u16);
        i += 1;
    }
    arr
}
pub const GROUP_20_OPTION_BOOL_INODES: [Inode; 20] = build_group_20_option_bool_inodes();

// 20 value bytes (1 = present-and-true, 0 = null-and-zeroed), followed by
// the same 3-byte validity bitmap as the list case above — no trailing
// alignment padding here, since a `Group`'s validity trailer is simply
// appended at the very end of the fixed region (see
// `primitive_group_option.rs`'s single-trailing-byte examples).
pub const GROUP_20_OPTION_BOOL: [u8; 23] = [
    0, 1, 1, 0, 1, 1, 0, 1, 1, 0, 1, 1, 0, 1, 1, 0, 1, 1, 0, 1, 182, 109, 11,
];

#[cfg_attr(test, tracing_test::traced_test)]
#[test]
fn test_nullability_group_option_bool_20() {
    let fields: Vec<PyroField> = (0..20)
        .map(|i| PyroField {
            name: format!("f{i}"),
            doc: String::new(),
            data_type: PyroType::OptionPrimitiveScalar {
                primitive: PrimitiveDataType::Bool,
            },
        })
        .collect();
    let schema = PyroSchema {
        doc: String::new(),
        fields,
    };

    let data = PyroValue::Group(
        (0..20u32)
            .map(|i| {
                let v = if i % 3 == 0 {
                    PyroValue::Null
                } else {
                    PyroValue::from(true)
                };
                (leaked(format!("f{i}")), v)
            })
            .collect(),
    );

    run_list_wrapped_roundtrip_u32(
        schema,
        data,
        &GROUP_20_OPTION_BOOL,
        &GROUP_20_OPTION_BOOL_INODES,
    );
}
